-- ---- public.get_users_for_organization(uuid)
CREATE OR REPLACE FUNCTION public.get_users_for_organization(org_id uuid)
 RETURNS TABLE(user_id uuid, email text, modules text[], role text, user_created_at timestamp with time zone, user_last_sign_in_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  select
    u.id,
    u.email::text,
    coalesce((select array_agg(distinct oa.module_id)
                from public.organization_apps oa
               where oa.organization_id = get_users_for_organization.org_id
                 and oa.module_id is not null), array[]::text[]),
    om.role::text,
    u.created_at,
    u.last_sign_in_at
  from public.organization_members om
  join auth.users u on om.user_id = u.id
  where om.organization_id = get_users_for_organization.org_id;
end;
$function$;
revoke execute on function public.get_users_for_organization(uuid) from public, anon, authenticated;
grant execute on function public.get_users_for_organization(uuid) to authenticated;
grant execute on function public.get_users_for_organization(uuid) to service_role;
-- ---- public.delete_organization(uuid)
CREATE OR REPLACE FUNCTION public.delete_organization(org_id_to_delete uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_super_admin() then
    raise exception 'Only Super Admins can delete organizations.';
  end if;

  delete from public.transactions where organization_id = org_id_to_delete;
  delete from public.invoices where organization_id = org_id_to_delete;
  delete from public.subscriptions where organization_id = org_id_to_delete;
  delete from public.organization_members where organization_id = org_id_to_delete;
  delete from public.organizations where id = org_id_to_delete;
end;
$function$;
revoke execute on function public.delete_organization(uuid) from public, anon, authenticated;
grant execute on function public.delete_organization(uuid) to anon, authenticated;
grant execute on function public.delete_organization(uuid) to service_role;
-- ---- public.hse_complete_org_setup(uuid)
CREATE OR REPLACE FUNCTION public.hse_complete_org_setup(p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_org_id IS NULL THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members m
    WHERE m.organization_id = p_org_id
      AND m.user_id = auth.uid()
      AND m.role IN ('owner', 'admin', 'org_admin')
      AND COALESCE(LOWER(m.status), 'active') = 'active'
  ) THEN
    RAISE EXCEPTION 'Only an organization admin can complete setup';
  END IF;

  UPDATE public.organizations
     SET setup_completed = true,
         setup_completed_at = COALESCE(setup_completed_at, NOW())
   WHERE id = p_org_id;

  RETURN true;
END;
$function$;
revoke execute on function public.hse_complete_org_setup(uuid) from public, anon, authenticated;
grant execute on function public.hse_complete_org_setup(uuid) to anon, authenticated;
grant execute on function public.hse_complete_org_setup(uuid) to service_role;
-- ---- public.update_last_accessed_app(text)
CREATE OR REPLACE FUNCTION public.update_last_accessed_app(p_app_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    UPDATE public.users
    SET last_accessed_app = p_app_name,
        updated_at = NOW()
    WHERE id = auth.uid();

    INSERT INTO public.app_activity_log (user_id, app_name, action)
    VALUES (auth.uid(), p_app_name, 'access');
END;
$function$;
revoke execute on function public.update_last_accessed_app(text) from public, anon, authenticated;
grant execute on function public.update_last_accessed_app(text) to anon, authenticated;
grant execute on function public.update_last_accessed_app(text) to service_role;
